#include <iostream>

int64_t reverseLastByte(int64_t n) {
    // Convert the integer to a string
    std::string str = std::to_string(n);

    // Find the last character (byte) in the string
    char lastByte = str[str.size() - 1];

    // Convert the last byte back to an integer and return
    return static_cast<int64_t>(lastByte);
}

int main() {
    int64_t number = 123456789;
    int64_t reversedNumber = reverseLastByte(number);

